import{_ as e,o,c as n,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"BrandHub — Backend API Completeness Audit","description":"","frontmatter":{},"headers":[],"relativePath":"plan/audit/backend-api-completeness-audit-2026-09-03.md","filePath":"plan/audit/backend-api-completeness-audit-2026-09-03.md"}'),d={name:"plan/audit/backend-api-completeness-audit-2026-09-03.md"};function i(r,t,a,s,h,g){return o(),n("div",null,[...t[0]||(t[0]=[c('<h1 id="brandhub-—-backend-api-completeness-audit" tabindex="-1">BrandHub — Backend API Completeness Audit <a class="header-anchor" href="#brandhub-—-backend-api-completeness-audit" aria-label="Permalink to &quot;BrandHub — Backend API Completeness Audit&quot;">​</a></h1><p>&gt; Phạm vi: các epic BACKEND còn task chưa Done trên Jira (theo snapshot phiên trước — không re-pull được Jira lần này, không có token khả dụng trong phiên audit này; dựa trên đối chiếu docs + code thực tế, coi code là nguồn sự thật). &gt; Nguồn đối chiếu: <code>docs/feature/*/spec.md</code> (business spec), <code>docs/api/endpoints/*.md</code> (API contract), source thực tế <code>brandhub-business-service</code>, <code>brandhub-ai-service</code>, <code>brandhub-publisher-service</code>. &gt; Ngày: 2026-09-03</p><p>&gt; <strong>⚠️ Cập nhật quan trọng (2026-09-03, verify lại có Jira token):</strong> Đã kiểm tra lại toàn bộ 17 epic &quot;Missing API&quot; trên Jira thật — <strong>task đã tồn tại đầy đủ và khớp đúng nghiệp vụ</strong>, không thiếu task. Ví dụ: E16 Client có 4 task (DA-220, 236, 249, 266 — In review), E28-E31 Content Workflow có route thiết kế mới hơn cả doc cũ (<code>/my-tasks</code>, <code>/account-review</code>, <code>/client-approve</code>, <code>/client-reject</code> — không phải generic <code>/approve</code>/<code>/reject</code> như <code>05_post.md</code> mô tả, nghĩa là <strong>doc API cũ đã lỗi thời so với task Jira</strong>, không phải Jira thiếu). <strong>Vấn đề thật sự là chưa ai code</strong>, không phải thiếu task để giao việc. Không tạo task Jira mới — xem mục 5 để biết việc cần làm tiếp theo.</p><hr><h2 id="_1-tong-quan" tabindex="-1">1. Tổng quan <a class="header-anchor" href="#_1-tong-quan" aria-label="Permalink to &quot;1. Tổng quan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Epic</th><th>Business area</th><th>Spec found?</th><th>API doc found?</th><th>Code found?</th><th>Verdict</th></tr></thead><tbody><tr><td>E12</td><td>OAuth login (Facebook, GitHub)</td><td>Có (<code>auth/oauth-social-login</code>)</td><td>Có (<code>01_auth.md</code>)</td><td>GitHub/Google/LinkedIn/Microsoft <strong>có</strong> controller; <strong>Facebook không có file nào</strong></td><td><strong>Missing API</strong></td></tr><tr><td>E15</td><td>Workspace (create/settings/member)</td><td>Có (<code>workspace-management/spec.md</code>)</td><td>Có (<code>03_workspace.md</code>)</td><td><code>WorkspaceController</code> đủ 14 endpoint khớp spec</td><td><strong>Complete</strong></td></tr><tr><td>E16</td><td>Client API (agency-client)</td><td>Không tìm thấy spec riêng trong <code>docs/feature/</code></td><td>Có, chi tiết (<code>04_client.md</code>, 8 endpoint)</td><td><strong>Không có</strong> <code>ClientController</code>/<code>ClientService</code> — chỉ có entity <code>Client.java</code></td><td><strong>Missing API</strong></td></tr><tr><td>E17</td><td>Subscription plans (Admin CRUD)</td><td>Không tìm thấy spec riêng</td><td>Có, chi tiết (<code>10_subscription.md</code>, 6 endpoint + Stripe)</td><td><strong>Không có</strong> controller/service — chỉ có entity <code>SubscriptionPlan.java</code>, <code>Invoice.java</code>, <code>Payment.java</code></td><td><strong>Missing API</strong></td></tr><tr><td>E18</td><td>Instagram OAuth connect</td><td>Không tìm thấy spec riêng</td><td>Có (<code>07_social_account.md</code>, generic <code>/social/connect/{platform}</code>)</td><td><strong>Không có</strong> <code>SocialAccountController</code>, không có model MongoDB <code>social_accounts</code></td><td><strong>Missing API</strong></td></tr><tr><td>E19</td><td>Zalo OA OAuth</td><td>Không tìm thấy spec riêng</td><td>Không có mục riêng (gộp trong <code>07_social_account.md</code> generic)</td><td><strong>Không có</strong> code</td><td><strong>Missing API</strong></td></tr><tr><td>E20</td><td>Token refresh scheduled job</td><td>Không tìm thấy spec riêng</td><td>Có (<code>POST /social/accounts/{id}/refresh</code>)</td><td><strong>Không có</strong> — phụ thuộc E18/E19 vốn cũng chưa có</td><td><strong>Missing API</strong></td></tr><tr><td>E21</td><td>Publisher — Threads/TikTok adapter</td><td>Không có spec</td><td>Không có tài liệu API riêng publisher-service</td><td><code>brandhub-publisher-service/src/main</code> chỉ có <code>BrandHubPublisherApplication.java</code> (bootstrap trống) — Jira nói &quot;In Progress&quot; nhưng repo chưa có code</td><td><strong>Missing API</strong> (nghiêm trọng — service rỗng)</td></tr><tr><td>E22</td><td>Publish callback → business-service</td><td>Không có spec</td><td>Không có</td><td>Không có endpoint nhận callback ở business-service, không có gì ở publisher-service</td><td><strong>Missing API</strong></td></tr><tr><td>E23</td><td>AI internal API wiring</td><td>Không có spec riêng (nằm rải trong AI feature)</td><td>Có (<code>12_api-endpoint-ai-service.md</code>, 771 dòng)</td><td><code>brandhub-ai-service</code> có router thật: content/image/video/ambassador/rag/trends — nhưng phía business-service <strong>không có gì gọi sang</strong> (không có <code>AiServiceClient</code>/proxy)</td><td><strong>Partial</strong></td></tr><tr><td>E24</td><td>Business-service AI integration flow</td><td>Không có spec</td><td>—</td><td>Không tìm thấy client/controller nào ở business-service gọi ai-service</td><td><strong>Missing API</strong></td></tr><tr><td>E28</td><td>Content request API</td><td>Không có spec riêng</td><td>Có (<code>06_content_request.md</code>, 6 endpoint)</td><td><strong>Không có</strong> controller/model</td><td><strong>Missing API</strong></td></tr><tr><td>E29</td><td>Assign content request</td><td>—</td><td>Nằm trong <code>06_content_request.md</code> (<code>PUT .../assign</code>)</td><td>Không có</td><td><strong>Missing API</strong></td></tr><tr><td>E30</td><td>Calendar/posts API</td><td>Không có spec riêng</td><td>Có (<code>05_post.md</code>, đủ approve/submit flow)</td><td><strong>Không có</strong> <code>PostController</code>/model</td><td><strong>Missing API</strong></td></tr><tr><td>E31</td><td>Account review/approve API</td><td>—</td><td>Nằm trong <code>05_post.md</code> (<code>/submit</code>, <code>/approve</code>)</td><td>Không có</td><td><strong>Missing API</strong></td></tr><tr><td>E32</td><td>Publisher — Facebook/social adapter</td><td>Không có spec</td><td>Không có</td><td>publisher-service rỗng (như E21)</td><td><strong>Missing API</strong></td></tr><tr><td>E33</td><td>Retry logic publish</td><td>Không có spec</td><td>Không có</td><td>Không có gì để có retry logic — publisher-service rỗng</td><td><strong>Missing API</strong></td></tr><tr><td>E38</td><td>Analytics aggregation API</td><td>Không có spec riêng</td><td>Có (<code>08_analytics.md</code>, 3 endpoint)</td><td>Không có <code>AnalyticsController</code>, không có <code>posts</code>/<code>ai_usage_logs</code> Mongo collection nào trong code</td><td><strong>Missing API</strong></td></tr><tr><td>E39</td><td>Notification CRUD API</td><td>Không có spec riêng</td><td>Không tìm thấy file endpoint riêng cho notification</td><td>Không có model/controller Notification</td><td><strong>Missing API</strong></td></tr><tr><td>E41</td><td>Firebase Cloud Messaging</td><td>—</td><td>—</td><td>Không có</td><td><strong>Missing API</strong></td></tr></tbody></table><p><strong>Đọc nhanh:</strong> Trong 19 epic backend business-logic được audit, chỉ <strong>1/19 (E15 – Workspace) là Complete</strong>. Còn lại 17 epic Missing API hoàn toàn (chưa có 1 dòng code controller/service nào), và 1 epic (E23) Partial — AI service có endpoint thật nhưng chưa được business-service gọi tới nên chưa dùng được end-to-end. Điều này khác biệt lớn so với Jira status &quot;In Review&quot;/&quot;In Progress&quot; ở một số epic (VD: E16 &quot;In review&quot;, E21 &quot;In Progress&quot;) — trạng thái Jira không phản ánh đúng thực tế code.</p><hr><h2 id="_2-chi-tiet-theo-epic-moi-epic-khac-complete" tabindex="-1">2. Chi tiết theo epic (mọi epic khác &quot;Complete&quot;) <a class="header-anchor" href="#_2-chi-tiet-theo-epic-moi-epic-khac-complete" aria-label="Permalink to &quot;2. Chi tiết theo epic (mọi epic khác &quot;Complete&quot;)&quot;">​</a></h2><h3 id="e12-—-oauth-facebook-login-da-613" tabindex="-1">E12 — OAuth Facebook login (DA-613) <a class="header-anchor" href="#e12-—-oauth-facebook-login-da-613" aria-label="Permalink to &quot;E12 — OAuth Facebook login (DA-613)&quot;">​</a></h3><ul><li>Spec (<code>auth/oauth-social-login/spec.md</code>) mô tả multi-provider OAuth theo pattern chung.</li><li>Code có đủ 4 provider: <code>GoogleOAuthController</code>, <code>GitHubOAuthController</code>, <code>LinkedInOAuthController</code>, <code>MicrosoftOAuthController</code> — mỗi controller có <code>/{provider}</code>, <code>/{provider}/link</code>, <code>/{provider}/callback</code>.</li><li><strong>Thiếu:</strong> không có <code>FacebookOAuthController</code> hay bất kỳ file nào chứa &quot;facebook&quot; trong toàn bộ <code>brandhub-business-service/src/main</code>. Jira nói task đang &quot;In Progress&quot; — khớp với thực tế chưa có code, không phải lỗi lệch trạng thái.</li><li>Việc build sẽ nhanh vì pattern đã có sẵn 4 lần lặp lại (copy <code>GitHubOAuthController</code> + <code>GitHubOAuthService</code>, đổi endpoint Facebook Graph API).</li></ul><h3 id="e16-—-client-api" tabindex="-1">E16 — Client API <a class="header-anchor" href="#e16-—-client-api" aria-label="Permalink to &quot;E16 — Client API&quot;">​</a></h3><ul><li>API doc yêu cầu 8 endpoint: create, list (scoped theo role), get, update, delete, assign manager, service-package, portal-access.</li><li>Model <code>Client.java</code> tồn tại (fields khớp doc: name, brandName, industry, contactEmail...) nhưng <strong>không có <code>ClientController</code>, <code>ClientService</code>, <code>ClientRepository</code></strong>.</li><li>Thiếu toàn bộ: không chỉ CRUD cơ bản mà cả nghiệp vụ isolation (<code>MANAGER</code> chỉ thấy client được assign, <code>CLIENT</code> chỉ thấy client của chính họ) — chưa có RBAC nào áp cho resource này vì chưa có controller.</li></ul><h3 id="e17-—-subscription-plans-crud" tabindex="-1">E17 — Subscription plans CRUD <a class="header-anchor" href="#e17-—-subscription-plans-crud" aria-label="Permalink to &quot;E17 — Subscription plans CRUD&quot;">​</a></h3><ul><li>Doc mô tả rõ luồng Stripe: <code>/plans</code> (public), <code>/current</code>, <code>/subscribe</code> (tạo <code>clientSecret</code>), <code>/webhook</code> (Stripe HMAC), <code>/cancel</code>, <code>/invoices</code>.</li><li>Model có <code>SubscriptionPlan</code>, <code>Invoice</code>, <code>Payment</code>, <code>WorkspaceSubscription</code>, enum <code>PaymentStatus</code>/<code>InvoiceStatus</code>/<code>SubscriptionStatus</code> — thiết kế DB đã sẵn sàng.</li><li><strong>Thiếu 100% code tầng service/controller.</strong> Đặc biệt nguy hiểm: <code>/webhook</code> cần raw-body signature validation (<code>STRIPE_WEBHOOK_SECRET</code>) — đây là điểm bảo mật quan trọng, chưa có gì để đánh giá được.</li></ul><h3 id="e18-e19-e20-—-social-oauth-connect-instagram-zalo-token-refresh-job" tabindex="-1">E18/E19/E20 — Social OAuth connect (Instagram, Zalo) + token refresh job <a class="header-anchor" href="#e18-e19-e20-—-social-oauth-connect-instagram-zalo-token-refresh-job" aria-label="Permalink to &quot;E18/E19/E20 — Social OAuth connect (Instagram, Zalo) + token refresh job&quot;">​</a></h3><ul><li>Doc gộp chung dưới <code>/api/v1/social/*</code> generic theo <code>{platform}</code> param, lưu MongoDB <code>social_accounts</code>.</li><li>Không có <code>SocialAccountController</code>, không thấy MongoDB entity/config nào cho collection này trong business-service (business-service dùng JPA/Postgres cho các model khác — cần xác nhận có tích hợp Mongo driver chưa, có vẻ chưa vì không thấy dependency Mongo trong cấu trúc các model liệt kê).</li><li>Token refresh job (E20) phụ thuộc hoàn toàn vào việc có OAuth token lưu trước — không thể build trước E18/E19.</li></ul><h3 id="e21-e32-e33-—-publisher-service-threads-tiktok-facebook-adapter-retry-logic" tabindex="-1">E21/E32/E33 — Publisher service (Threads/TikTok/Facebook adapter, retry logic) <a class="header-anchor" href="#e21-e32-e33-—-publisher-service-threads-tiktok-facebook-adapter-retry-logic" aria-label="Permalink to &quot;E21/E32/E33 — Publisher service (Threads/TikTok/Facebook adapter, retry logic)&quot;">​</a></h3><ul><li><strong>Phát hiện nghiêm trọng nhất của audit này:</strong> <code>brandhub-publisher-service/src/main/java/com/brandhub/publisher/</code> chỉ có đúng 1 file — <code>BrandHubPublisherApplication.java</code> (Spring Boot bootstrap trống, không route, không adapter, không retry, không queue).</li><li>Jira ghi nhận DA-214 (Threads adapter) và DA-272 (TikTok adapter) đang <strong>In Progress</strong> — nhưng không có bất kỳ commit/class nào phản ánh việc đó trong repo hiện tại. Cần xác nhận trực tiếp với Phước — có thể code đang nằm ở branch riêng chưa merge, hoặc Jira status sai.</li><li>Không có gì để đánh giá &quot;exponential backoff&quot;, &quot;dead-letter-queue&quot;, hay &quot;per-platform rate limit&quot; vì chưa có adapter nào tồn tại.</li></ul><h3 id="e22-—-publish-callback-→-business-service" tabindex="-1">E22 — Publish callback → business-service <a class="header-anchor" href="#e22-—-publish-callback-→-business-service" aria-label="Permalink to &quot;E22 — Publish callback → business-service&quot;">​</a></h3><ul><li>Không tìm thấy endpoint nào ở <code>business-service</code> để nhận callback trạng thái publish (VD: <code>POST /api/v1/posts/{id}/publish-status</code>). Vì publisher-service chưa có gì gọi ra ngoài, callback contract cũng chưa được định nghĩa ở cả hai phía.</li></ul><h3 id="e23-e24-—-ai-service-wiring" tabindex="-1">E23/E24 — AI service wiring <a class="header-anchor" href="#e23-e24-—-ai-service-wiring" aria-label="Permalink to &quot;E23/E24 — AI service wiring&quot;">​</a></h3><ul><li><code>brandhub-ai-service</code> là service <strong>duy nhất trong 3 backend service có code triển khai thật</strong> — router FastAPI đủ 6 domain: content, image, video, ambassador, rag, trends (khớp <code>12_api-endpoint-ai-service.md</code>, 771 dòng doc — tài liệu dài nhất, phản ánh đây là phần được đầu tư nhiều nhất).</li><li><strong>Thiếu (E24):</strong> phía <code>business-service</code> không có <code>AiServiceClient</code>, <code>RestTemplate</code>/<code>WebClient</code> bean, hay controller nào forward request sang ai-service. Nghĩa là AI service hoạt động độc lập, nhưng chưa được business-service &quot;wiring&quot; vào — frontend không thể gọi AI qua business-service, phải gọi thẳng ai-service (nếu vậy thì thiếu auth/workspace-scoping ở tầng gateway).</li><li>Verdict &quot;Partial&quot; cho E23 vì AI-side code tồn tại thật, nhưng &quot;Missing API&quot; cho E24 vì phần wiring hoàn toàn chưa có.</li></ul><h3 id="e28-e29-—-content-request-api" tabindex="-1">E28/E29 — Content request API <a class="header-anchor" href="#e28-e29-—-content-request-api" aria-label="Permalink to &quot;E28/E29 — Content request API&quot;">​</a></h3><ul><li>Doc yêu cầu 6 endpoint gồm workflow assign + comment thread.</li><li>Không có <code>ContentRequest</code> model, controller, hay repository nào trong business-service. Đây là workflow cốt lõi kết nối Client → Manager → Creator — hiện không thể thực hiện được qua API dù đã có role model (<code>MemberRole</code> enum) sẵn sàng ở tầng Workspace.</li></ul><h3 id="e30-e31-—-calendar-posts-approve" tabindex="-1">E30/E31 — Calendar/Posts + Approve <a class="header-anchor" href="#e30-e31-—-calendar-posts-approve" aria-label="Permalink to &quot;E30/E31 — Calendar/Posts + Approve&quot;">​</a></h3><ul><li>Doc mô tả rõ approval chain: <code>POST /posts</code> (Creator/AM tạo) → <code>PUT .../submit</code> → <code>PUT .../approve</code>.</li><li>Không có <code>Post</code> model/controller nào. Approval chain (Creator → Manager → Client) <strong>hoàn toàn không thể đi qua được</strong> vì chưa có transition endpoint nào tồn tại — không phải &quot;thiếu 1 state&quot; mà là thiếu toàn bộ luồng.</li></ul><h3 id="e38-—-analytics-aggregation" tabindex="-1">E38 — Analytics aggregation <a class="header-anchor" href="#e38-—-analytics-aggregation" aria-label="Permalink to &quot;E38 — Analytics aggregation&quot;">​</a></h3><ul><li>Doc yêu cầu MongoDB aggregation trên <code>posts</code>/<code>ai_usage_logs</code>. Vì <code>posts</code> (E30) và social/AI usage tracking chưa tồn tại, analytics không có nguồn dữ liệu để tổng hợp dù có build controller cũng vô nghĩa — <strong>phụ thuộc cứng vào E28-E31 xong trước.</strong></li></ul><h3 id="e39-e41-—-notification-fcm" tabindex="-1">E39/E41 — Notification + FCM <a class="header-anchor" href="#e39-e41-—-notification-fcm" aria-label="Permalink to &quot;E39/E41 — Notification + FCM&quot;">​</a></h3><ul><li>Không tìm thấy file endpoint riêng cho Notification trong <code>docs/api/endpoints/</code> (không có <code>13_notification.md</code> hay tương đương) — nghĩa là ngay cả tài liệu hoá API cũng chưa có, không chỉ code. Cần làm rõ contract trước khi build.</li></ul><hr><h2 id="_3-cross-cutting-findings" tabindex="-1">3. Cross-cutting findings <a class="header-anchor" href="#_3-cross-cutting-findings" aria-label="Permalink to &quot;3. Cross-cutting findings&quot;">​</a></h2><ol><li><strong>Role naming lệch giữa doc và code:</strong> <code>docs/api/endpoints/*.md</code> dùng <code>OWNER / MANAGER / CREATOR / CLIENT</code>, nhưng code thực tế (<code>MemberRole</code> enum, <code>workspace-management/spec.md</code>) dùng <code>OWNER / CREATOR / VIEWER / CLIENT / ACCOUNT</code>. Toàn bộ <code>docs/api/endpoints/04_client.md</code> đến <code>11_admin.md</code> có khả năng là tài liệu cũ/aspirational viết trước khi role model chốt lại — cần review lại toàn bộ trước khi dùng làm spec để code, không chỉ các epic liệt kê ở đây.</li><li><strong>Jira status không đáng tin cậy làm tín hiệu tiến độ code:</strong> E16 &quot;In review&quot; và E21 &quot;In Progress&quot; nhưng repo tương ứng không có code phản ánh. Nên đối chiếu trực tiếp branch/PR thay vì chỉ tin Jira status khi ước lượng % hoàn thành.</li><li><strong>Publisher-service là điểm nghẽn lớn nhất:</strong> toàn bộ nhóm E21/E22/E32/E33 (publish core) phụ thuộc vào 1 service hiện đang trống hoàn toàn. Đây là rủi ro capstone lớn nhất nếu deadline gần.</li><li><strong>Chuỗi phụ thuộc chưa được thứ tự hoá đúng trên Jira:</strong> E38 (Analytics) phụ thuộc E30/E31 (Post); E20 (token refresh) phụ thuộc E18/E19 (social OAuth); E24 phụ thuộc E23. Nếu các epic phụ thuộc bị làm song song không đúng thứ tự sẽ phải làm lại.</li><li><strong>Workspace (E15) là chuẩn tốt để nhân bản:</strong> có <code>@RequireRole</code> aspect, soft-delete pattern, business rule &quot;last owner&quot; đã implement đúng theo spec — nên dùng làm template khi build Client/Post/ContentRequest controller thay vì thiết kế lại từ đầu.</li><li><strong>Chưa thấy MongoDB config nào trong business-service</strong> dù nhiều doc (Social Account, Analytics) giả định lưu Mongo — cần xác nhận dependency <code>spring-boot-starter-data-mongodb</code> đã có trong <code>pom.xml</code> chưa trước khi bắt đầu E18/E38.</li></ol><hr><h2 id="_4-uu-tien-xay-tiep-theo-muc-đo-toi-quan-trong-nghiep-vu" tabindex="-1">4. Ưu tiên xây tiếp (theo mức độ tối quan trọng nghiệp vụ) <a class="header-anchor" href="#_4-uu-tien-xay-tiep-theo-muc-đo-toi-quan-trong-nghiep-vu" aria-label="Permalink to &quot;4. Ưu tiên xây tiếp (theo mức độ tối quan trọng nghiệp vụ)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Epic</th><th>Lý do ưu tiên</th></tr></thead><tbody><tr><td>1</td><td>E30/E31 — Post + Approve API</td><td>Lõi nghiệp vụ nội dung, mọi thứ khác (Analytics, Content Request) phụ thuộc vào đây</td></tr><tr><td>2</td><td>E28/E29 — Content Request API</td><td>Điểm vào của luồng Client → AM → Creator, cần song song với E30</td></tr><tr><td>3</td><td>E21/E32/E33 — Publisher service (adapter + retry)</td><td>Service đang hoàn toàn trống, publish là giá trị cốt lõi sản phẩm, rủi ro deadline cao nhất</td></tr><tr><td>4</td><td>E16 — Client API</td><td>Nền tảng multi-tenant agency-client, đã có model + doc sẵn, chỉ cần build (nhanh)</td></tr><tr><td>5</td><td>E24 — Wiring business-service ↔ ai-service</td><td>AI service đã có code thật, &quot;chỉ&quot; thiếu lớp gọi — effort thấp, giá trị cao</td></tr><tr><td>6</td><td>E18/E19/E20 — Social OAuth connect + refresh</td><td>Cần trước khi publisher-service (E32) có gì để publish tới</td></tr><tr><td>7</td><td>E12 — Facebook OAuth</td><td>Effort thấp (copy pattern GitHub/Google), nhưng không chặn epic khác</td></tr><tr><td>8</td><td>E17 — Subscription CRUD</td><td>Quan trọng cho monetization nhưng không chặn luồng demo core</td></tr><tr><td>9</td><td>E38 — Analytics</td><td>Phụ thuộc cứng vào E30/E31 xong trước, không nên bắt đầu sớm</td></tr><tr><td>10</td><td>E39/E41 — Notification + FCM</td><td>Chưa có cả doc, độ ưu tiên thấp nhất cho MVP capstone</td></tr></tbody></table><hr><h2 id="_5-verify-lai-voi-jira-that-2026-09-03-—-task-đa-đu-khong-tao-task-moi" tabindex="-1">5. Verify lại với Jira thật (2026-09-03) — task đã đủ, KHÔNG tạo task mới <a class="header-anchor" href="#_5-verify-lai-voi-jira-that-2026-09-03-—-task-đa-đu-khong-tao-task-moi" aria-label="Permalink to &quot;5. Verify lại với Jira thật (2026-09-03) — task đã đủ, KHÔNG tạo task mới&quot;">​</a></h2><p>Sau khi có token Jira, đối chiếu lại toàn bộ 17 epic &quot;Missing API&quot; với task thật trên Jira. <strong>Kết luận: task đã có sẵn, khớp đúng nghiệp vụ, không thiếu task để giao việc.</strong> Vấn đề duy nhất là code chưa làm — đúng như audit gốc đã kết luận, nhưng khác ở chỗ <strong>không cần tạo thêm task mới</strong>, chỉ cần bắt tay vào code theo task đã có.</p><p><strong>Phát hiện quan trọng khác với audit gốc:</strong></p><ul><li><strong>E12 (OAuth) đã Done phần lớn</strong> — 7/10 task Done (Register, Login, Refresh, Logout, Forgot/Reset Password, Change Password), chỉ 3 task chưa xong: Google (In review), Facebook + GitHub (In Progress). Audit gốc chỉ nói &quot;thiếu Facebook&quot; — thực tế đã có người đang làm cả Facebook lẫn GitHub.</li><li><strong>E21 (Publisher Core) đã Done 3/6</strong> — Init project, RabbitMQ consumer, Instagram adapter đều Done. Facebook adapter đang In review. Chỉ Threads + TikTok adapter còn thật sự chưa xong (In Progress). Audit gốc kết luận &quot;service hoàn toàn trống&quot; dựa trên việc chỉ thấy 1 file bootstrap trong repo — <strong>có khả năng code đang nằm ở nhánh/PR chưa merge vào main</strong>, cần Phước xác nhận trực tiếp thay vì tin theo audit code-scan.</li><li><strong>E28-E31 (Content Workflow) có route thiết kế mới hơn doc cũ</strong> — Jira dùng <code>/my-tasks</code>, <code>/account-review</code>, <code>/client-approve</code>, <code>/client-reject</code> thay vì generic <code>/approve</code>/<code>/reject</code> như <code>05_post.md</code> mô tả. Doc API cần cập nhật lại theo task Jira, không phải ngược lại.</li><li><strong>Doc endpoint (<code>docs/api/endpoints/*.md</code>) đã lỗi thời ở nhiều chỗ</strong> — số lượng endpoint trong doc không khớp số task Jira thực tế (VD E16 doc ghi 8 endpoint, Jira chỉ giao 4 task — có thể 4 endpoint còn lại đã được gộp/bỏ theo quyết định thiết kế mới chưa cập nhật lại doc).</li></ul><p><strong>Bảng còn lại chính xác (theo task Jira thật, không phải audit code-scan cũ):</strong></p><table tabindex="0"><thead><tr><th>Epic</th><th>Epic key</th><th>Done</th><th>Còn lại</th><th>Người phụ trách chính</th></tr></thead><tbody><tr><td>E12 Auth/OAuth</td><td>DA-92</td><td>7/10</td><td>Google (review), Facebook + GitHub (In Progress)</td><td>Trung</td></tr><tr><td>E16 Client</td><td>DA-102</td><td>0/4</td><td>Toàn bộ 4 task đang In review — chờ merge, không phải chưa code</td><td>Trung (assign)</td></tr><tr><td>E17 Subscription</td><td>DA-107</td><td>0/4</td><td>Toàn bộ 4 task To Do</td><td>Ân</td></tr><tr><td>E18 Meta OAuth (FB+IG)</td><td>DA-103</td><td>0/4</td><td>Toàn bộ 4 task To Do</td><td>Phước, Trung</td></tr><tr><td>E19 TikTok/Threads/Zalo OAuth</td><td>DA-108</td><td>0/4</td><td>Toàn bộ 4 task To Do</td><td>Phước, Trung</td></tr><tr><td>E20 Token Lifecycle</td><td>DA-100</td><td>0/3</td><td>Toàn bộ 3 task To Do</td><td>Trung, Phước</td></tr><tr><td>E21 Publisher Core</td><td>DA-105</td><td>3/6</td><td>Threads + TikTok adapter (In Progress)</td><td>Phước</td></tr><tr><td>E22 Publish Callback</td><td>DA-95</td><td>0/3</td><td>Toàn bộ 3 task To Do</td><td>Phước, Trung</td></tr><tr><td>E24 AI wiring</td><td>DA-101</td><td>0/3</td><td>Toàn bộ 3 task <strong>Unassigned</strong> — cần giao gấp</td><td>Chưa có</td></tr><tr><td>E28 Content Request</td><td>DA-112</td><td>0/3</td><td>Toàn bộ 3 task To Do</td><td>Phước</td></tr><tr><td>E29 Task Assignment</td><td>DA-120</td><td>0/3</td><td>Toàn bộ 3 task To Do</td><td>Phước</td></tr><tr><td>E30 Content Calendar</td><td>DA-114</td><td>0/4</td><td>Toàn bộ 4 task To Do (2 API + 2 FE component)</td><td>Phước</td></tr><tr><td>E31 Approval Workflow</td><td>DA-115</td><td>0/4</td><td>Toàn bộ 4 task To Do</td><td>Phước</td></tr><tr><td>E32 Publishing System</td><td>DA-113</td><td>0/8</td><td>Toàn bộ 8 task To Do (Facebook/IG/TikTok/Threads/Zalo adapter + Smart Ingestion + RabbitMQ consumer + callback)</td><td>Phước</td></tr><tr><td>E33 Publish Error Handling</td><td>DA-118</td><td>0/3</td><td>Toàn bộ 3 task To Do</td><td>Phước, Trung</td></tr><tr><td>E38 Analytics</td><td>DA-125</td><td>0/4</td><td>Toàn bộ 4 task To Do (2 API + 1 FE + 1 email)</td><td>—</td></tr><tr><td>E39 Notification</td><td>DA-121</td><td>0/3</td><td>Toàn bộ 3 task To Do</td><td>Trung, Phước</td></tr><tr><td>E41 Mobile Notifications</td><td>DA-127</td><td>0/4</td><td>Toàn bộ 4 task To Do</td><td>Phước, Trung</td></tr></tbody></table><p><strong>Việc cần làm ngay (không tạo task Jira mới):</strong></p><ol><li><strong>Giao gấp 3 task E24 (Unassigned)</strong> — DA-221, DA-238, DA-258 — đây là điểm nối AI service (đã chạy thật) vào business-service, effort thấp/giá trị cao nhất theo mục 4.</li><li><strong>Xác nhận với Phước về E21 Publisher</strong> — code có tồn tại ở branch riêng chưa merge hay thật sự chưa bắt đầu Threads/TikTok adapter?</li><li><strong>Cập nhật <code>docs/api/endpoints/*.md</code></strong> cho khớp route thật đã thiết kế trong Jira (đặc biệt E28-E31, E16) — doc hiện dùng route cũ không khớp task đang code.</li><li><strong>Không cần tạo thêm Jira task</strong> cho 17 epic này — toàn bộ đã có task đúng người đúng việc, chỉ cần đẩy code.</li></ol><hr><p><em>Audit gốc thực hiện bằng cách đối chiếu trực tiếp source code 3 service (<code>business</code>, <code>ai</code>, <code>publisher</code>) với <code>docs/feature/*/spec.md</code> và <code>docs/api/endpoints/*.md</code>, không có Jira token khả dụng lúc đó. Mục 5 verify lại bằng Jira API thật (token Personal API Token, Basic Auth) ngày 2026-09-03 — số liệu mục 5 là nguồn chính xác nhất, ưu tiên hơn kết luận &quot;Missing API&quot; ở mục 1-4 vốn chỉ dựa trên code-scan.</em></p>',48)])])}const p=e(d,[["render",i]]);export{u as __pageData,p as default};
